        $s=$this->loadShare($token);if($s->permission_level!=='edit')throw new ApiException(403,'الرابط للعرض فقط');if(!in_array($s->status,['draft','revision_requested','client_review'],true))throw new ApiException(409,'العقد لا يقبل تعديلات مشاركة في حالته الحالية');$data=$request->validate(['publicId'=>['nullable','string','max:40'],'fieldValues'=>['required','array']]);$publicId=strtoupper($data['publicId']??'');if($s->target_public_id&&strtoupper($s->target_public_id)!==$publicId)throw new ApiException(403,'Z-ID غير مطابق للدعوة');$editable=array_fill_keys($this->jsonList($s->editable_field_keys),true);$unauthorized=array_values(array_filter(array_keys($data['fieldValues']),fn($key)=>!isset($editable[$key])));if($unauthorized)throw new ApiException(403,'تتضمن التعديلات حقولًا غير مسموح بها','SHARE_FIELDS_FORBIDDEN',$unauthorized);
