        DB::transaction(function()use($request,$s,$merged,$status,$data){DB::statement('UPDATE contracts SET field_values_json=?::jsonb,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[json_encode($merged,JSON_UNESCAPED_UNICODE),$status,$s->contract_id]);DB::statement('UPDATE contract_versions SET field_values_json=?::jsonb,status=? WHERE id=(SELECT current_version_id FROM contracts WHERE id=?)',[json_encode($merged,JSON_UNESCAPED_UNICODE),$status,$s->contract_id]);$this->notifications->notify((int)($s->client_user_id??$s->user_id),'contract_shared_update','تم تعديل بيانات من رابط المشاركة',"{$s->serial_number}: توجد تعديلات تحتاج مراجعتك","/contract/{$s->contract_id}");$this->audit->write($request,'contract.shared_fields_updated','contract',(int)$s->contract_id,$this->json($s->field_values_json),$data['fieldValues'],null);});
        return$this->ok($request,['contractId'=>(int)$s->contract_id,'status'=>$status,'issues'=>$validation['issues']],'تم حفظ التعديلات وإشعار صاحب العقد');
    }

    public function createDraft(Request $request)
