        $auth=$this->auth($request);$this->verified($auth);$data=$request->validate(['templateSlug'=>['nullable','string','max:100'],'slug'=>['nullable','string','max:100'],'variantKey'=>['nullable','string','max:140'],'selectedOptionalClauseKeys'=>['nullable','array'],'fieldValues'=>['nullable','array'],'formData'=>['nullable','array'],'attachmentRefs'=>['nullable','array'],'currentStepKey'=>['nullable','string','max:140'],'sourceChannel'=>['nullable','in:customer,office'],'creationMode'=>['nullable','in:self_service,lawyer_assisted,office_assisted'],'mode'=>['nullable','in:self_service,lawyer_assisted,office_assisted'],'officeContext'=>['nullable','array']]);
