        $template=$this->publishedTemplate($slug);$definition=$template['definition'];$variantKey=$data['variantKey']??(count($definition['variants']??[])===1?($definition['variants'][0]['key']??null):null);if(!$variantKey)throw new ApiException(400,'يجب اختيار نوع العقد');$optional=array_values(array_map('strval',$data['selectedOptionalClauseKeys']??[]));$fields=$data['fieldValues']??$data['formData']??[];$attachments=$data['attachmentRefs']??[];$validation=$this->engine->validateDraft($definition,$variantKey,$optional,$fields,$attachments);
        $variant=collect($definition['variants']??[])->firstWhere('key',$variantKey);$clientId=$source==='customer'?$auth['id']:null;$owner=$clientId??$auth['id'];$office=$data['officeContext']??null;$billing='client_invoice';$waiver=null;$assigned=null;if($source==='office'){if(!$office)throw new ApiException(400,'بيانات إنشاء العقد من المكتب مطلوبة');$billing=$office['billingMode']??'client_invoice';$waiver=$office['waiverReason']??null;if(($office['clientMode']??null)==='existing')$clientId=(int)($office['clientId']??0);$owner=$clientId?:$auth['id'];$assigned=!empty($office['assignedLawyerId'])?(int)$office['assignedLawyerId']:null;}
        $serial=$this->serial($slug);$result=DB::transaction(function()use($request,$auth,$data,$template,$definition,$variant,$variantKey,$optional,$fields,$attachments,$source,$mode,$clientId,$owner,$office,$billing,$waiver,$assigned,$serial){$row=DB::selectOne("INSERT INTO contracts(serial_number,user_id,client_user_id,created_by_user_id,template_id,template_version_id,creation_mode,source_channel,status,core_identity_locked,template_version,variant_key,selected_optional_clause_keys,field_values_json,attachment_refs_json,current_step_key,title,billing_mode,original_price_egp,waiver_reason,assigned_lawyer_id) VALUES (?,?,?,?,?,?,?,?,'draft',FALSE,?,?,?::jsonb,?::jsonb,?::jsonb,?,?,?,?,?,?) RETURNING id",[$serial,$owner,$clientId,$auth['id'],$template['templateId'],$template['versionId'],$mode,$source,$definition['version'],$variantKey,json_encode($optional),json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($attachments,JSON_UNESCAPED_UNICODE),$data['currentStepKey']??($variant['steps'][0]['key']??'start'),$variant['documentTitleAr']??$variant['nameAr'],$billing,$definition['priceEgp']??0,$waiver,$assigned]);$id=(int)$row->id;$this->linkContractAttachments($attachments,$auth['id'],$id);$ver=DB::selectOne("INSERT INTO contract_versions(contract_id,version_number,template_version,template_version_id,variant_key,selected_optional_clause_keys,field_values_json,legal_clause_snapshot_json,status,created_by) VALUES (?,1,?,?,?,?,?::jsonb,'[]'::jsonb,'draft',?) RETURNING id",[$id,$definition['version'],$template['versionId'],$variantKey,json_encode($optional),json_encode($fields,JSON_UNESCAPED_UNICODE),$auth['id']]);DB::table('contracts')->where('id',$id)->update(['current_version_id'=>$ver->id]);if($source==='office'&&$office)DB::insert('INSERT INTO contract_office_contexts(contract_id,created_by_staff_id,assigned_lawyer_id,client_mode,client_snapshot_json,billing_mode,original_price_egp,waiver_reason,notify_client) VALUES (?,?,?,?,?::jsonb,?,?,?,?)',[$id,$auth['id']