    public function createShare(Request $request,int $id)
    {
        $auth=$this->auth($request);$c=$this->contract($id);$this->assertAccess($auth,$c);$data=$request->validate(['permission'=>['nullable','in:view_only,edit'],'targetPublicId'=>['nullable','string','max:32'],'expiresInDays'=>['nullable','integer','min:1','max:30'],'editableFieldKeys'=>['nullable','array','max:100'],'editableFieldKeys.*'=>['string','max:140']]);$permission=($data['permission']??'view_only')==='edit'?'edit':'view_only';if(!config('zdraft.features.contract_editing'))$permission='view_only';if($permission==='edit'&&!in_array($c->status,['draft','revision_requested','client_review'],true))throw new ApiException(409,'يمكن مشاركة النسخة الحالية للعرض فقط');$window=$this->editWindow($c->edit_expires_at);if($permission==='edit'&&$c->status==='client_review'&&!$window['active'])throw new ApiException(409,'انتهت مهلة تعديل العقد ويمكن مشاركته للعرض فقط','EDIT_WINDOW_EXPIRED');$target=!empty($data['targetPublicId'])?strtoupper($data['targetPublicId']):null;if($target&&!DB::selectOne('SELECT 1 FROM users WHERE upper(public_id)=upper(?)',[$target]))throw new ApiException(400,'Z-ID المستهدف غير موجود');$editable=[];if($permission==='edit'){$core=array_fill_keys($this->engine->coreIdentityFieldKeys($this->json($c->template_definition),$c->variant_key),true);foreach(array_unique($data['editableFieldKeys']??[])as$key)if(!($c->core_identity_locked&&isset($core[$key])))$editable[]=$key;}$raw=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$expires=$data['expiresInDays']??7;$row=DB::selectOne("INSERT INTO contract_share_links(contract_id,created_by_user_id,token_hash,permission_level,target_public_id,editable_field_keys,expires_at) VALUES (?,?,?,?,?,?::jsonb,CURRENT_TIMESTAMP + (?::text || ' days')::interval) RETURNING id,expires_at",[$id,$auth['id'],hash('sha256',$raw),$permission,$target,json_encode($editable),$expires]);$this->audit->write($request,'contract.share_created','contract_share',(int)$row->id,null,['contractId'=>$id,'permission'=>$permissio