    }
    public function revokeShare(Request $request,int $id,int $shareId){$auth=$this->auth($request);$c=$this->contract($id);$this->assertAccess($auth,$c);$count=DB::table('contract_share_links')->where('id',$shareId)->where('contract_id',$id)->whereNull('revoked_at')->update(['revoked_at'=>now()]);if(!$count)throw new ApiException(404,'رابط المشاركة غير موجود أو ملغى');$this->audit->write($request,'contract.share_revoked','contract_share',$shareId,null,['contractId'=>$id]);return$this->ok($request,['revoked'=>true],'تم إلغاء رابط المشاركة');}
    public function my(Request $request){$uid=$this->auth($request)['id'];$rows=DB::select('SELECT c.id,c.serial_number AS "serialNumber",c.title,c.status,c.source_channel AS "sourceChannel",c.variant_key AS "variantKey",c.updated_at AS "updatedAt",ct.slug AS "templateSlug",ct.name_ar AS "templateNameAr" FROM contracts c JOIN contract_templates ct ON ct.id=c.template_id WHERE c.deleted_at IS NULL AND (c.user_id=? OR c.client_user_id=? OR c.created_by_user_id=? OR c.assigned_lawyer_id=?) ORDER BY c.updated_at DESC',[$uid,$uid,$uid,$uid]);return$this->ok($request,$rows);}

    public function pdf(Request $request,int $id):BinaryFileResponse
    {
        $auth=$this->auth($request);$c=$this->contract($id);$this->assertAccess($auth,$c);if($c->status!=='issued'||$c->pdf_status!=='ready'||!$c->pdf_path)throw new ApiException(409,'النسخة النهائية غير جاهزة للتنزيل بعد','PDF_NOT_READY');$doc=DB::selectOne("SELECT storage_path,storage_key FROM contract_document_files WHERE contract_id=? AND contract_version_id=? AND document_type='main' ORDER BY id DESC LIMIT 1",[$id,$c->current_version_id]);$path=$this->contractPath($doc->storage_key??null,$doc->storage_path??$c->pdf_path);if(!is_file($path))throw new ApiException(404,'ملف العقد غير موجود في التخزين','PDF_FILE_MISSING');return response()->download($path,preg_replace('/[^A-Za-z0-9._-]/','-',"{$c->serial_number}.pdf"),['Content-Type'=>'application/pdf']);
    }
    public function documents(Request $request,int $id){$auth=$this->auth($request);$c=$this->contract($id);$this->assertAccess($auth,$c);$rows=DB::select('SELECT id,file_key AS "fileKey",document_type AS "documentType",optional_clause_key AS "optionalClauseKey",title_ar AS "titleAr",file_size_bytes AS "fileSizeBytes",sha256,created_at AS "createdAt" FROM contract_document_files WHERE contract_id=? AND contract_version_id=? ORDER BY CASE WHEN document_type=\'main\' THEN 0 ELSE 1 END,id',[$id,$c->current_version_id]);return$this->ok($request,$rows);}
    public function downloadDocument(Request $request,int $id,int $documentId):BinaryFileResponse{$auth=$this->auth($request);$c=$this->contract($id);$this->assertAccess($auth,$c);$doc=DB::selectOne('SELECT storage_path,storage_key,title_ar FROM contract_document_files WHERE id=? AND contract_id=? AND contract_version_id=?',[$documentId,$id,$c->current_version_id]);if(!$doc)throw new ApiException(404,'المستند غير موجود');$path=$this->contractPath($doc->storage_key??null,$doc->storage_path);if(!is_file($path))throw new ApiException(404,'ملف المستند غير موجود في التخزين','DOCUMENT_FILE_MISSING');$name=preg_replace('/[^A-Za-z0-9._-]+/','-',"{$c->serial_number}-{$doc->title_ar}.pdf");return response()->download($path,$name,['Content-Type'=>'application/pdf']);}

    public function show(Request $request,int $id)
    {
        $auth=$this->auth($request);$c=$this->contract($id);$this->assertAccess($auth,$c);$versions=DB::select('SELECT id,version_number AS "versionNumber",status,created_at AS "createdAt",locked_at AS "lockedAt",document_hash AS "documentHash",pdf_path AS "pdfPath" FROM contract_versions WHERE contract_id=? ORDER BY version_number DESC',[$id]);$definition=$this->json($c->template_definition);$optional=$this->jsonList($c->selected_optional_clause_keys);$window=$this->editWindow($c->edit_expires_at);$isOwner=in_array($auth['id'],[(int)$c->user_id,(int)($c->client_user_id??0)],true);$canDraft=in_array($c->status,['draft','revision_requested'],true);$canWindow=$isOwner&&$c->creation_mode==='self_service'&&$c->status==='client_review'&&$window['active'];$payload=$this->objectArray($c);$payload['template_definition']=$definition;$payload['field_values_json']=$this->json($c->field_values_json);$payload['selected_optional_clause_keys']=$optional;$payload['attachment_refs_json']=$this->json($c->attachment_refs_json);$payload['legal_clause_snapshot_json']=$this->jsonList($c->legal_clause_snapshot_json);$payload['versions']=$versions;$payload['coreIdentityFieldKeys']=$this->engine->coreIdentityFieldKeys($definition,$c->variant_key);$payload['fieldMetadata']=$this->fieldMetadata($definition,$c->variant_key,$optional);$payload['editWindow']=$window+['expiresAt'=>$c->edit_expires_at];$payload['permissions']=['canEdit'=>$canDraft||$canWindow,'canEditCoreIdentity'=>$canDraft&&!$c->core_identity_locked,'canRequestRevision'=>$isOwner&&in_array($c->status,['client_review','approved'],true),'canDownloadPdf'=>$c->status==='issued'&&$c->pdf_status==='ready'&&(bool)$c->pdf_path];return$this->ok($request,$payload);
    }

    public function updateDraft(Request $request,int $id)
    {
        $auth=$this->auth($request);$c=$this->contract($id);$this->assertAccess($auth,$c);$isOwner=in_array($auth['id'],[(int)$c->user_id,(int)($c->client_user_id??0)],true);$window=$this->editWindow($c->edit_expires_at);$ordinary=in_array($c->status,['draft','revision_requested'],true);$selfWindow=$isOwner&&$c->creation_mode==='self_service'&&$c->status==='client_review'&&$window['active'];if(!$ordinary&&!$selfWindow){if($c->creation_mode==='self_service'&&$c->status==='client_review'&&$window['expired'])throw new ApiException(409,'انتهت مهلة التعديل. اطلب خدمة تصحيح أو مراجعة من المكتب','EDIT_WINDOW_EXPIRED');throw new ApiException(409,'لا يمكن تعديل العقد في حالته الحالية');}
        $data=$request->validate(['fieldValues'=>['nullable','array'],'selectedOptionalClauseKeys'=>['nullable','array'],'variantKey'=>['nullable','string','max:140'],'attachmentRefs'=>['nullable','array'],'currentStepKey'=>['nullable','string','max:140']]);$currentFields=$this->json($c->field_values_json);$fields=$data['fieldValues']??$currentFields;$currentOptional=$this->jsonList($c->selected_optional_clause_keys);$optional=array_key_exists('selectedOptionalClauseKeys',$data)?array_map('strval',$data['selectedOptionalClauseKeys']):$currentOptional;$variant=$data['variantKey']??$c->variant_key;$attachments=$data['attachmentRefs']??$this->json($c->attachment_refs_json);$definition=$this->json($c->template_definition);
        if($selfWindow||$c->core_identity_locked){if($variant!==$c->variant_key)throw new ApiException(409,'لا يمكن تغيير نوع العقد بعد اعتماد الدفع','CONTRACT_VARIANT_LOCKED');if(json_encode($optional)!==json_encode($currentOptional))throw new ApiException(409,'لا يمكن تغيير الملاحق أو البنود المختارة بعد اعتماد الدفع','CONTRACT_OPTIONS_LOCKED');$core=array_fill_keys($this->engine->coreIdentityFieldKeys($definition,$c->variant_key),true);$changed=[];foreach(array_unique(array_merge(array_keys($currentFields),array_keys($fields)))as$key)if(json_encode($currentFields[$key]??null)!==json_encode($fields[$key]??null)&&isset($core[$key]))$changed[]=$key;if($changed)throw new ApiException(409,'بيانات الأطراف والعقار مقفلة بعد اعتماد الدفع','CORE_IDENTITY_LOCKED',$changed);}
        $validation=$this->engine->validateDraft($definition,$variant,$optional,$fields,$attachments);DB::transaction(function()use($request,$auth,$c,$id,$fields,$optional,$variant,$data,$attachments,$selfWindow){DB::statement('UPDATE contracts SET field_values_json=?::jsonb,selected_optional_clause_keys=?::jsonb,attachment_refs_json=?::jsonb,current_step_key=COALESCE(?,current_step_key),variant_key=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($optional),json_encode($attachments,JSON_UNESCAPED_UNICODE),$data['currentStepKey']??null,$variant,$id]);DB::statement("UPDATE contract_versions SET field_values_json=?::jsonb,selected_optional_clause_keys=?::jsonb,variant_key=? WHERE id=? AND status IN ('draft','revision_requested','client_review','internal_review')",[json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($optional),$variant,$c->current_version_id]);if(isset($data['attachmentRefs']))$this->linkContractAttachments($attachments,$auth['id'],$id);$this->audit->write($request,$selfWindow?'contract.edit_window_updated':'contract.draft_updated','contract',$id,$this->json($c->field_values_json),$fields);});return$this->ok($request,['id'=>$id,'serialNumber'=>$c->serial_number,'status'=>$c->status,'currentVersionId'=>(int)$c->current_version_id,'editExpiresAt'=>$c->edit_expires_at,'issues'=>$validation['issues']],$validation['issues']?'تم الحفظ مع وجود بيانات مطلوبة':'تم حفظ التعديلات');
    }

    public function submit(Request $request,int $id)
    {
