    public function adminIndex(Request $request){$auth=$this->auth($request);$status=$request->filled('status')?$request->string('status')->toString():null;$source=$request->filled('source')?$request->string('source')->toString():null;$search=$request->filled('search')?'%'.$request->string('search')->toString().'%':null;$viewAll=in_array('super_admin',$auth['roles']??[],true)||in_array('contracts.view_all',$auth['permissions']??[],true);$assigned=!$viewAll||$request->boolean('assignedToMe');$rows=DB::select('SELECT c.id,c.serial_number AS "serialNumber",c.title,c.status,c.source_channel AS "sourceChannel",c.billing_mode AS "billingMode",c.original_price_egp::float AS "originalPriceEgp",c.updated_at AS "updatedAt",ct.name_ar AS "templateNameAr",ct.slug AS "templateSlug",COALESCE(client.name,coc.client_snapshot_json->>\'name\',\'استخدام داخلي\') AS "clientName",lawyer.name AS "assignedLawyerName",creator.name AS "createdByName" FROM contracts c JOIN contract_templates ct ON ct.id=c.template_id LEFT JOIN users client ON client.id=COALESCE(c.client_user_id,c.user_id) LEFT JOIN users lawyer ON lawyer.id=c.assigned_lawyer_id LEFT JOIN users creator ON creator.id=c.created_by_user_id LEFT JOIN contract_office_contexts coc ON coc.contract_id=c.id WHERE c.deleted_at IS NULL AND (?::text IS NULL OR c.status=?) AND (?::text IS NULL OR c.source_channel=?) AND (?::text IS NULL OR c.serial_number ILIKE ? OR c.title ILIKE ? OR client.name ILIKE ?) AND (?::boolean=FALSE OR c.assigned_lawyer_id=?) ORDER BY c.updated_at DESC LIMIT 200',[$status,$status,$source,$source,$search,$search,$search,$search,$assigned,$auth['id']]);return$this->ok($request,$rows);}
    public function assign(Request $request,int $id){if(!config('zdraft.features.assignment'))throw new ApiException(404,'ميزة إسناد المحامين مخفية حاليًا','FEATURE_DISABLED');$data=$request->validate(['lawyerId'=>['required','integer','min:1']]);if(!DB::selectOne("SELECT u.id FROM users u JOIN staff_role_assignments sra ON sra.user_id=u.id JOIN roles r ON r.id=sra.role_id WHERE u.id=? AND r.role_key='lawyer' AND u.status='active'",[$data['lawyerId']]))throw new ApiException(400,'الحساب المختار ليس محاميًا نشطًا');DB::transaction(function()use($request,$id,$data){DB::statement("UPDATE contracts SET assigned_lawyer_id=?,status=CASE WHEN status='pending_review' THEN 'assigned' ELSE status END,updated_at=CURRENT_TIMESTAMP WHERE id=?",[$data['lawyerId'],$id]);$this->notifications->notify((int)$data['lawyerId'],'contract_assigned','تم إسناد عقد جديد إليك',"العقد رقم {$id} متاح في قائمة عملك","/contracts/{$id}");$this->audit->write($request,'contract.assigned','contract',$id,null,['lawyerId'=>$data['lawyerId']]);});return$this->ok($request,['id'=>$id,'lawyerId'=>(int)$data['lawyerId']],'تم إسناد العقد');}
