    public function createVersion(Request $request,int $id){if(!config('zdraft.features.contract_editing'))throw new ApiException(404,'تعديل العقود من لوحة التحكم مخفي حاليًا','FEATURE_DISABLED');$auth=$this->auth($request);$c=$this->contract($id);$this->assertStaff($auth,$c);$result=DB::transaction(function()use($request,$auth,$c,$id){DB::selectOne('SELECT id FROM contracts WHERE id=? FOR UPDATE',[$id]);$next=(int)DB::selectOne('SELECT COALESCE(MAX(version_number),0)+1 AS next FROM contract_versions WHERE contract_id=?',[$id])->next;$row=DB::selectOne("INSERT INTO contract_versions(contract_id,version_number,parent_version_id,template_version,template_version_id,variant_key,selected_optional_clause_keys,field_values_json,legal_clause_snapshot_json,status,created_by) VALUES (?,?,?,?,?,?,?::jsonb,?::jsonb,?::jsonb,'draft',?) RETURNING id",[$id,$next,$c->current_version_id,$c->template_version,$c->template_version_id,$c->variant_key,json_encode($this->jsonList($c->selected_optional_clause_keys)),json_encode($this->json($c->field_values_json),JSON_UNESCAPED_UNICODE),json_encode($this->jsonList($c->legal_clause_snapshot_json),JSON_UNESCAPED_UNICODE),$auth['id']]);DB::statement("UPDATE contracts SET current_version_id=?,status='in_progress',core_identity_locked=FALSE,updated_at=CURRENT_TIMESTAMP WHERE id=?",[$row->id,$id]);$this->audit->write($request,'contract.version_created','contract',$id,null,['versionNumber'=>$next,'versionId'=>$row->id]);return['versionId'=>(int)$row->id,'versionNumber'=>$next];});return$this->created($request,$result,'تم إنشاء إصدار تعديل جديد مع الاحتفاظ بالإصدار السابق');}
    public function updateVersion(Request $request,int $id,int $versionId){if(!config('zdraft.features.contract_editing'))throw new ApiException(404,'تعديل العقود من لوحة التحكم مخفي حاليًا','FEATURE_DISABLED');$auth=$this->auth($request);$c=$this->contract($id);$this->assertStaff($auth,$c);if((int)$c->current_version_id!==$versionId)throw new ApiException(409,'يمكن تعديل الإصدار الحالي فقط');$v=DB::selectOne('SELECT status FROM contract_versions WHERE id=? AND contract_id=?',[$versionId,$id]);if(!$v)throw new ApiException(404,'إصدار العقد غير موجود');if(!in_array($v->status,['draft','internal_review','revision_requested'],true))throw new ApiException(409,'الإصدار مقفول أو غير قابل للتعديل');$data=$request->validate(['fieldValues'=>['nullable','array'],'selectedOptionalClauseKeys'=>['nullable','array'],'variantKey'=>['nullable','string','max:140'],'attachmentRefs'=>['nullable','array'],'currentStepKey'=>['nullable','string','max:140'],'notes'=>['nullable','string','max:5000']]);$fields=$data['fieldValues']??$this->json($c->field_values_json);$optional=$data['selectedOptionalClauseKeys']??$this->jsonList($c->selected_optional_clause_keys);$variant=$data['variantKey']??$c->variant_key;$attachments=$data['attachmentRefs']??$this->json($c->attachment_refs_json);$validation=$this->engine->validateDraft($this->json($c->template_definition),$variant,$optional,$fields,$attachments);DB::transaction(function()use($request,$auth,$c,$id,$versionId,$data,$fields,$optional,$variant,$attachments){DB::statement("UPDATE contract_versions SET field_values_json=?::jsonb,selected_optional_clause_keys=?::jsonb,variant_key=?,status='draft' WHERE id=? AND contract_id=?",[json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($optional),$variant,$versionId,$id]);DB::statement("UPDATE contracts SET field_values_json=?::jsonb,selected_optional_clause_keys=?::jsonb,variant_key=?,attachment_refs_json=?::jsonb,current_step_key=COALESCE(?,current_step_key),status='in_progress',updated_at=CURRENT_TIMESTAMP WHERE id=?",[json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($optional),$variant,json_encode($attachments,JSON_UNESCAPED_UNICODE),$data['currentStepKey']??null,$id]);if(isset($data['attachmentRefs']))$this->linkContractAttachments($attachments,$auth['id'],$id);$this->audit->write($request,'contract.version_updated','contract_version',$versionId,$this->json($c->field_values_json),['fieldValues'=>$fields,'optionalKeys'=>$optional,'variantKey'=>$variant,'notes'=>$data['notes']??null]);});return$this->ok($request,['contractId'=>$id,'versionId'=>$versionId,'issues'=>$validation['issues']],$validation['issues']?'تم حفظ الإصدار مع وجود بيانات مطلوبة':'تم حفظ إصدار العقد');}
    public function lock(Request $request,int $id){$auth=$this->auth($request);$c=$this->contract($id);$this->assertStaff($auth,$c);if(!in_array($c->status,['approved','client_review','in_progress'],true))throw new ApiException(409,'يجب استكمال المراجعة قبل قفل العقد');$result=$this->lockSnapshot($request,$c,$auth['id']);return$this->ok($request,['id'=>$id,'status'=>'locked','documentHash'=>$result['documentHash']],'تم قفل العقد وإنشاء لقطة قانونية ثابتة');}
    public function issue(Request $request,int $id){$auth=$this->auth($request);$c=$this->contract($id);$this->assertStaff($auth,$c);if($c->status!=='locked')throw new ApiException(409,'يجب قفل العقد قبل إصداره');DB::transaction(function()use($request,$auth,$c,$id){DB::statement("UPDATE contracts SET status='issued',pdf_status='queued',issued_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?",[$id]);DB::table('contract_versions')->where('id',$c->current_version_id)->update(['status'=>'issued']);DB::insert("INSERT INTO document_jobs(contract_id,contract_version_id,job_type,status,payload_json) VALUES (?,?,'generate_pdf','pending',?::jsonb)",[$id,$c->current_version_id,json_encode(['requestedBy'=>$auth['id']])]);$this->notifications->notify((int)($c->client_user_id??$c->user_id),'contract_issued','تم إصدار عقدك',"{$c->serial_number}: يجري تجهيز ملف PDF النهائي","/contract/{$id}");$this->audit->write($request,'contract.issued','contract',$id,null,['queuedPdf'=>true]);});return$this->ok($request,['id'=>$id,'status'=>'issued','pdfJobQueued'=>true],'تم إصدار العقد وإضافة توليد PDF إلى قائمة المهام');}

    private function lockAndQueue(Request $request,object $c,int $actor,bool $force):array{$locked=$this->lockSnapshot($request,$c,$actor);DB::transaction(function()use($request,$c,$actor){DB::statement("UPDATE contracts SET status='issued',pdf_status='queued',issued_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?",[$c->id]);DB::table('contract_versions')->where('id',$c->current_version_id)->update(['status'=>'issued']);DB::insert("INSERT INTO document_jobs(contract_id,contract_version_id,job_type,status,payload_json) VALUES (?,?,'generate_pdf','pending',?::jsonb)",[$c->id,$c->current_version_id,json_encode(['requestedBy'=>$actor])]);$this->notifications->notify($actor,'contract_issued','تم إصدار النسخة النهائية',"{$c->serial_number}: يجري تجهيز ملف PDF","/contract/{$c->id}");$this->audit->write($request,'contract.self_service_issued_early','contract',(int)$c->id,null,['documentHash'=>$this->currentHash((int)$c->current_version_id)]);});return$locked;}
    private function lockSnapshot(Request $request,object $c,int $actor):array{$definition=$this->json($c->template_definition);$fields=$this->json($c->field_values_json);$optional=$this->jsonList($c->selected_optional_clause_keys);$validation=$this->engine->validateDraft($definition,$c->variant_key,$optional,$fields,$this->json($c->attachment_refs_json));if($validation['issues'])throw new ApiException(422,'لا يمكن قفل عقد ببيانات ناقصة','DRAFT_INCOMPLETE',$validation['issues']);$rendered=$this->engine->renderLegalClauses($definition,$c->variant_key,$optional,$fields);if($rendered['missingClauseKeys'])throw new ApiException(422,'القالب لا يحتوي بعد على النصوص القانونية الكاملة لكل المواد المطلوبة','MISSING_LEGAL_CLAUSES',$rendered['missingClauseKeys']);if($rendered['missingVariables'])throw new ApiException(422,'توجد متغيرات قانونية بلا قيم','MISSING_LEGAL_VARIABLES',$rendered['missingVariables']);$snapshot=['templateVersionId'=>$c->template_version_id,'variantKey'=>$c->variant_key,'optionalKeys'=>$optional,'fieldValues'=>$fields,'clauses'=>$rendered['clauses']];$hash=hash('sha256',$this->stableJson($snapshot));DB::transaction(function()use($request,$c,$rendered,$hash){DB::statement("UPDATE contract_versions SET legal_clause_snapshot_json=?::jsonb,status='locked',document_hash=?,locked_at=CURRENT_TIMESTAMP WHERE id=?",[json_encode($rendered['clauses'],JSON_UNESCAPED_UNICODE),$hash,$c->current_version_id]);DB::statement("UPDATE contracts SET status='locked',core_identity_locked=TRUE,locked_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?",[$c->id]);$this->audit->write($request,'contract.locked','contract',(int)$c->id,null,['documentHash'=>$hash,'versionId'=>$c->current_version_id]);});return['documentHash'=>$hash];}

    private function auth(Request $r):array{return$r->attributes->get('auth_user')??throw new ApiException(401,'يجب تسجيل الدخول أولًا','UNAUTHENTICATED');}
    private function verified(array $a):void{if(!($a['emailVerified']??false))throw new ApiException(403,'يجب تأكيد البريد الإلكتروني أولًا','EMAIL_NOT_VERIFIED');}
    private function contract(int $id):object{$c=DB::selectOne('SELECT c.*,ct.slug AS template_slug,ct.name_ar AS template_name_ar,tv.definition_json AS template_definition,cv.version_number,cv.status AS version_status,cv.legal_clause_snapshot_json,u.name AS client_name,u.email AS client_email,lawyer.name AS assigned_lawyer_name,coc.client_snapshot_json,coc.billing_mode AS office_billing_mode,coc.waiver_reason AS office_waiver_reason,latest_payment.status AS payment_status,latest_payment.amount_egp AS payment_amount_egp,latest_payment.admin_notes AS payment_admin_notes,latest_payment.serial_number AS payment_serial_number FROM contracts c JOIN contract_templates ct ON ct.id=c.template_id JOIN template_versions tv ON tv.id=c.template_version_id LEFT JOIN contract_versions cv ON cv.id=c.current_version_id LEFT JOIN users u ON u.id=COALESCE(c.client_user_id,c.user_id) LEFT JOIN users lawyer ON lawyer.id=c.assigned_lawyer_id LEFT JOIN contract_office_contexts coc ON coc.contract_id=c.id LEFT JOIN LATERAL (SELECT p.status,p.amount_egp,p.admin_notes,p.serial_number FROM payments p WHERE p.contract_id=c.id ORDER BY p.created_at DESC,p.id DESC LIMIT 1) latest_payment ON TRUE WHERE c.id=? AND c.deleted_at IS NULL',[$id]);if(!$c)throw new ApiException(404,'العقد غير موجود');return$c;}
    private function assertAccess(array $a,object $c):void{if(in_array('super_admin',$a['roles']??[],true)||in_array('contracts.view_all',$a['permissions']??[],true)||in_array($a['id'],array_map('intval',array_filter([$c->user_id,$c->client_user_id,$c->created_by_user_id,$c->assigned_lawyer_id])),true))return;throw new ApiException(403,'ليس لديك صلاحية عرض هذا العقد');}
    private function assertStaff(array $a,object $c):void{if(in_array('super_admin',$a['roles']??[],true)||in_array('contracts.view_all',$a['permissions']??[],true)||(in_array('contracts.view_assigned',$a['permissions']??[],true)&&(int)$c->assigned_lawyer_id===$a['id']))return;throw new ApiException(403,'هذا العقد غير مسند إليك','CONTRACT_NOT_ASSIGNED');}
    private function publishedTemplate(string $slug):array{$r=DB::selectOne("SELECT ct.id AS template_id,tv.id AS version_id,tv.definition_json FROM contract_templates ct JOIN template_versions tv ON tv.id=ct.current_published_version_id WHERE ct.slug=? AND ct.is_active=TRUE AND tv.status='published'",[$slug]);if(!$r)throw new ApiException(404,'القالب المنشور غير موجود','TEMPLATE_NOT_PUBLISHED');return['templateId'=>(int)$r->template_id,'versionId'=>(int)$r->version_id,'definition'=>$this->json($r->definition_json)];}
    private function loadShare(string $token):object{$r=DB::selectOne('SELECT sl.*,c.serial_number,c.title,c.status,c.user_id,c.client_user_id,c.created_by_user_id,c.assigned_lawyer_id,c.field_values_json,c.attachment_refs_json,c.variant_key,c.selected_optional_clause_keys,c.template_version_id,c.core_identity_locked,c.edit_expires_at,tv.definition_json AS template_definition,ct.slug AS template_slug,owner.name AS owner_name FROM contract_share_links sl JOIN contracts c ON c.id=sl.contract_id JOIN contract_templates ct ON ct.id=c.template_id JOIN template_versions tv ON tv.id=c.template_version_id JOIN users owner ON owner.id=COALESCE(c.client_user_id,c.user_id) WHERE sl.token_hash=? AND sl.revoked_at IS NULL AND sl.expires_at>CURRENT_TIMESTAMP AND c.deleted_at IS NULL',[hash('sha256',$token)]);if(!$r)throw new ApiException(404,'رابط المشاركة غير صالح أو منتهي','SHARE_LINK_INVALID');return$r;}
    private function linkContractAttachments(array $refs,int $owner,int $contractId):void{$ids=[];foreach($refs as $values)if(is_array($values))foreach($values as$v)if(filter_var($v,FILTER_VALIDATE_INT)!==false)$ids[]=(int)$v;$ids=array_values(array_unique($ids));if(!$ids)return;$pg='{'.implode(',',$ids).'}';$rows=DB::select("SELECT id FROM document_attachments WHERE id=ANY(?::bigint[]) AND owner_user_id=? AND (attachable_type='pending' OR (attachable_type='contract' AND attachable_id=?)) FOR UPDATE",[$pg,$owner,$contractId]);if(count($rows)!==count($ids))throw new ApiException(400,'يوجد مرفق عقد غير صالح أو مرتبط بسجل آخر');DB::statement("UPDATE document_attachments SET attachable_type='contract',attachable_id=? WHERE id=ANY(?::bigint[]) AND attachable_type='pending'",[$contractId,$pg]);}
    private function editWindow(mixed $expires):array{if(!$expires)return['active'=>false,'expired'=>false,'remainingSeconds'=>0];$seconds=max(0,strtotime((string)$expires)-time());return['active'=>$seconds>0,'expired'=>$seconds<=0,'remainingSeconds'=>$seconds];}
    private function fieldMetadata(array $def,string $variant,array $optional):array{$resolved=$this->engine->resolve($def,$variant,$optional,[]);$out=[];foreach($resolved['steps']as$step)foreach($step['fields']??[]as$field)$out[$field['key']]=['labelAr'=>$field['labelAr']??$field['key'],'type'=>$field['type']??'text','options'=>$field['options']??[]];return$out;}
    private function contractPath(?string $key,string $legacy):string{if($key){try{return Storage::disk('contracts')->path($key);}catch(\Throwable){}}return$legacy;}
    private function serial(string $slug):string{return'SCP-'.now()->year.'-'.strtoupper(substr($slug,0,3)).'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,8));}
    private function maskName(string $name):string{$parts=preg_split('/\s+/u',trim($name))?:[];return implode(' ',array_map(fn($p,$i)=>$i===0?$p:mb_substr($p,0,1).'***',$parts,array_keys($parts)));}
    private function json(mixed $v):array{if(is_array($v))return$v;if(is_object($v))return(array)$v;if(is_string($v))return json_decode($v,true)?:[];return[];}
    private function jsonList(mixed $v):array{return array_values($this->json($v));}
    private function objectArray(object $o):array{return get_object_vars($o);}
    private function stableJson(mixed $value):string{return json_encode($this->canonical($value),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION);}
    private function canonical(mixed $value):mixed{if(!is_array($value))return$value;if(array_is_list($value))return array_map(fn($v)=>$this->canonical($v),$value);ksort($value);foreach($value as$k=>$v)$value[$k]=$this->canonical($v);return$value;}
    private function currentHash(int $version):?string{return DB::selectOne('SELECT document_hash FROM contract_versions WHERE id=?',[$version])?->document_hash;}
}
